/**
 * @vitest-environment jsdom
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, act, waitFor } from '@testing-library/react';
import HomePage from '@/app/(dashboard)/home/page';
import { DynamicForm as ActualDynamicForm } from '@/components/DynamicForm';
import { templates } from '@/lib/templates';
import { useExecutionStore } from '@/lib/store';
import type { Execution } from '@/types';

const navigation = vi.hoisted(() => ({ params: new URLSearchParams() }));

vi.mock('next/navigation', () => ({
    useRouter: () => ({ push: vi.fn(), replace: vi.fn() }),
    useSearchParams: () => navigation.params,
}));

vi.mock('@/lib/i18n', () => ({
    useLanguage: () => ({ language: 'en', t: (key: string) => key }),
}));

vi.mock('@/components/SpecExport', () => ({ SpecExport: () => null }));
vi.mock('@/lib/skill-template-map', () => ({ getSkillForTemplate: () => null }));

vi.mock('@/lib/analytics', () => ({
    trackEvent: vi.fn(),
}));

vi.mock('@/components/Settings', () => ({
    useSettings: () => ({ settings: { providers: {} } }),
}));

vi.mock('@/lib/hooks/useExecute', () => {
    const providers: never[] = [];
    const fetchProviders = () => undefined;
    return {
        useProviders: () => ({ providers, anyConfigured: false, fetchProviders }),
    };
});

// Leaf controls are replaced by stubs that expose their callbacks as buttons.
// The Home page and the execution store stay real.
vi.mock('@/components', async () => ({
    DynamicForm: (await import('@/components/DynamicForm')).DynamicForm,
    ProcessingScreen: (props: { onComplete: (output: string) => void; onCancel: () => void }) => (
        <div data-testid="processing-screen">
            <button onClick={props.onCancel}>cancel-processing</button>
            <button onClick={() => props.onComplete('OUTPUT_NEW')}>complete-processing</button>
        </div>
    ),
    ResultViewer: (props: {
        execution: Execution;
        output: string;
        onAccept: () => void;
        onReject: () => void;
        onRetry: () => void;
        onFollowUp?: (refinement: string) => void;
    }) => (
        <div data-testid="result-viewer">
            <span data-testid="result-id">{props.execution.id}</span>
            <span data-testid="result-template">{props.execution.templateId}</span>
            <span data-testid="result-output">{props.output}</span>
            <button onClick={props.onAccept}>accept</button>
            <button onClick={props.onReject}>reject</button>
            <button onClick={props.onRetry}>retry</button>
            <button onClick={() => props.onFollowUp?.('refine it')}>follow-up</button>
        </div>
    ),
    TemplatePreviewModal: () => null,
    OnboardingTour: () => null,
    AppBuilderWizard: () => null,
    ProductDesignWizard: () => null,
    MarketingCampaignWizard: () => null,
    BusinessStrategyWizard: () => null,
    SecurityAssessmentWizard: () => null,
    ResearchProjectWizard: () => null,
    SystemDesignWizard: () => null,
    ContentStrategyWizard: () => null,
    DataAnalysisWizard: () => null,
}));

vi.mock('@/components/home/HomeBrowseExperience', () => ({
    HomeBrowseExperience: (props: {
        templates: Array<{ id: string }>;
        handleSelectTemplate: (template: unknown) => void;
    }) => (
        <div data-testid="home-browse-experience">
            <button onClick={() => props.handleSelectTemplate(props.templates.find(t => t.id === 'documentation'))}>
                pick-documentation
            </button>
        </div>
    ),
}));

const documentation = templates.find(t => !t.isFolder && t.id === 'documentation')!;
const otherTemplate = templates.find(t => !t.isFolder && t.id !== documentation.id)!;

// Each call builds an independent object so that A, B and the other fixtures
// can never alias one another.
function fixture(id: string, output: string, overrides: Partial<Execution> = {}): Execution {
    return {
        id,
        templateId: documentation.id,
        templateName: documentation.name,
        category: documentation.category,
        input: { topic: `${id} topic` },
        intent: `${id} intent`,
        output,
        status: 'completed',
        createdAt: new Date('2026-10-11T00:00:00Z'),
        ...overrides,
    };
}

const buildA = () => fixture('exec_fixture_A', 'OUTPUT_A', {
    result: 'accepted',
    threadId: 'thread_A',
    rootExecutionId: 'root_A',
    projectLabel: 'Project A',
    knowledgeCollectionId: 'kc_A',
});

const buildB = () => fixture('exec_fixture_B', 'OUTPUT_B', {
    threadId: 'thread_B',
    rootExecutionId: 'root_B',
    projectLabel: 'Project B',
    knowledgeCollectionId: 'kc_B',
});

const buildC = () => fixture('exec_fixture_C', 'OUTPUT_C', {
    templateId: otherTemplate.id,
    templateName: otherTemplate.name,
    category: otherTemplate.category,
    result: 'accepted',
    threadId: 'thread_C',
    rootExecutionId: 'root_C',
});

const buildUnaccepted = () => fixture('exec_fixture_R', 'OUTPUT_R', { result: 'rejected' });
const buildEmptyOutput = () => fixture('exec_fixture_E', '', { result: 'accepted' });
const buildMissingTemplate = () => fixture('exec_fixture_T', 'OUTPUT_T', {
    result: 'accepted',
    templateId: 'template_missing_fixture',
});

function seed(executions: Execution[], current: Execution | null) {
    useExecutionStore.setState({ executions, currentExecution: current });
}

function openHistory(id: string) {
    navigation.params = new URLSearchParams(`continue=${id}`);
}

function byId(id: string) {
    return useExecutionStore.getState().executions.find(e => e.id === id);
}

function click(name: string) {
    fireEvent.click(screen.getByRole('button', { name }));
}

function startFreshRun() {
    click('pick-documentation');
    click('submit-form');
}

beforeEach(() => {
    vi.restoreAllMocks();
    localStorage.clear();
    sessionStorage.clear();
    navigation.params = new URLSearchParams();
    useExecutionStore.setState({ executions: [], currentExecution: null });
});


const draft = { subject: 'Selected draft A', currentNotes: 'Notes only for A', readerGoal: 'Recover without typing again' };
function fill() {
    for (const [name,value] of Object.entries(draft)) fireEvent.change(document.querySelector('[name="'+name+'"]')!, {target:{value}});
}
async function submit() {
    fireEvent.submit(document.querySelector('form')!);
    await waitFor(() => expect(screen.getByTestId('processing-screen')).toBeTruthy());
}
async function start() { render(<HomePage />); click('pick-documentation'); fill(); await submit(); return useExecutionStore.getState().executions[0].id; }

describe('Local selected draft isolation challenge', () => {
    it('positive: selected stop persists only failed A while ambient B survives', async () => {
        const id=await start(); const b=buildB(); act(()=>useExecutionStore.getState().addExecution(b)); const before=JSON.stringify(b);
        click('cancel-processing'); expect(byId(id)?.status).toBe('failed'); expect(JSON.stringify(byId(b.id))).toBe(before);
        expect((document.querySelector('[name="subject"]') as HTMLInputElement).value).toBe(draft.subject);
        expect(JSON.parse(localStorage.getItem('cvf-executions-storage')!).state.executions.find((e:Execution)=>e.id===id).status).toBe('failed');
    });
    it('positive: constant-clock resubmit completes C independently of saved A', async () => {
        vi.spyOn(Date,'now').mockReturnValue(1791763200000);
        const id=await start(); click('complete-processing'); const before=JSON.stringify(byId(id)); click('retry');
        fireEvent.change(document.querySelector('[name="subject"]')!,{target:{value:'Edited C'}}); await submit();
        const c=useExecutionStore.getState().executions[0].id; expect(c).not.toBe(id); click('complete-processing');
        expect(byId(c)?.input.subject).toBe('Edited C'); expect(JSON.stringify(byId(id))).toBe(before);
    });
    it('negative: live template query switch clears old DOM and submitted field set', async () => {
        const view=render(<HomePage />); click('pick-documentation'); fill(); await submit(); click('cancel-processing');
        const before=JSON.stringify(useExecutionStore.getState().executions);
        navigation.params=new URLSearchParams('template=strategy_analysis'); view.rerender(<HomePage />);
        await waitFor(()=>expect(document.querySelector('[name="topic"]')).toBeTruthy());
        const values=Array.from(document.querySelectorAll('input,textarea,select')).map(e=>(e as HTMLInputElement).value);
        expect(values).not.toContain(draft.subject); expect(values).not.toContain(draft.currentNotes);
        expect((document.querySelector('[name="topic"]') as HTMLInputElement).value).toBe('');
        expect(JSON.stringify(useExecutionStore.getState().executions)).toBe(before);
        fireEvent.change(document.querySelector('[name="topic"]')!,{target:{value:'New B topic'}});
        fireEvent.change(document.querySelector('[name="context"]')!,{target:{value:'New B context'}});
        await submit();
        const input=useExecutionStore.getState().executions[0].input;
        expect(input.subject).toBeUndefined(); expect(input.currentNotes).toBeUndefined(); expect(input.readerGoal).toBeUndefined();
        expect(input.topic).toBe('New B topic'); expect(input.context).toBe('New B context');
    });
    it('negative: same-template query fresh choice clears recovered values', async () => {
        const view=render(<HomePage />); click('pick-documentation'); fill(); await submit(); click('cancel-processing');
        navigation.params=new URLSearchParams('template=documentation'); view.rerender(<HomePage />);
        await waitFor(()=>expect((document.querySelector('[name="subject"]') as HTMLInputElement).value).toBe(''));
        expect(screen.queryByTestId('draft-stop-notice')).toBeNull(); expect(useExecutionStore.getState().executions).toHaveLength(1);
    });
});
